import{_ as t,o,c as a,a4 as r}from"./chunks/framework.DpieW3qv.js";const h=JSON.parse('{"title":"CategoryService","description":"","frontmatter":{},"headers":[],"relativePath":"future/CATEGORY-SERVICE.md","filePath":"future/CATEGORY-SERVICE.md","lastUpdated":null}'),i={name:"future/CATEGORY-SERVICE.md"};function s(d,e,n,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="categoryservice" tabindex="-1">CategoryService <a class="header-anchor" href="#categoryservice" aria-label="Permalink to &quot;CategoryService&quot;">​</a></h1><blockquote><p>OCAPI-backed category resolution for SFCC. Enables runtime lookup of category IDs → URL paths and supports EPLP and future category-driven features.</p></blockquote><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Category IDs (e.g. <code>cat1510004</code>) are stored in brand config (<code>contextIds</code>) for slot resolution, but full preview URLs (e.g. <code>/sale/ann-coupons-and-special-offers/cat1510004/</code>) require SFCC to resolve the path. This service fetches category data from OCAPI and provides:</p><ul><li><strong>Category ID → URL path resolution</strong> — for preview links (COUPONS, PLP_HEADER, EPLP)</li><li><strong>Parent–child category tree</strong> — for EPLP and PLP selection workflows</li><li><strong>CLI support</strong> — <code>make categories</code> (or similar) to browse the tree</li></ul><h2 id="proposed-solution" tabindex="-1">Proposed Solution <a class="header-anchor" href="#proposed-solution" aria-label="Permalink to &quot;Proposed Solution&quot;">​</a></h2><ul><li><strong>CategoryService</strong> (<code>src/infrastructure/sfcc/OcapiServices/CategoryService.js</code>): OCAPI calls for category metadata (e.g. <code>GET /sites/{siteId}/categories/{id}</code> with <code>levels=2</code>).</li><li><strong>FetchCategories use case</strong>: Build tree, return <code>{ id, name, path, children[] }</code>.</li><li><strong>CLI</strong>: <code>make categories [BRAND=] [--output=tree|json]</code>.</li><li><strong>Preview URL resolution</strong>: When building &quot;Open in SFCC&quot; links for category-scoped assets (COUPONS, PLP_HEADER, EPLP), call CategoryService to resolve <code>contextIds[assetType]</code> → path, then append to <code>preview_link</code>.</li></ul><h2 id="implementation-plan" tabindex="-1">Implementation Plan <a class="header-anchor" href="#implementation-plan" aria-label="Permalink to &quot;Implementation Plan&quot;">​</a></h2><ol><li>Add CategoryService with <code>getCategory(siteId, categoryId, options)</code>.</li><li>Add FetchCategories use case and <code>handleCategories</code> CLI command.</li><li>Add CategoryService to BrandContext.</li><li>Use it in status/preview to build preview URLs for category-scoped asset types.</li><li>Remove hardcoded <code>assetPages</code> entries for category-scoped types once resolution works.</li></ol><h2 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Estimate</th></tr></thead><tbody><tr><td>Design</td><td>1 day</td></tr><tr><td>Development</td><td>2–3 days</td></tr><tr><td>Testing</td><td>1 day</td></tr></tbody></table><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li>OCAPI category endpoints</li><li>Existing <code>contextIds</code> in brand config (<code>sfcc.config.js</code>)</li></ul>',14)])])}const g=t(i,[["render",s]]);export{h as __pageData,g as default};
